// The trend builder's data (proposed D-63): the prepared history as a lazy same-origin chunk (public played games
// only, generated by scripts/prepare-trend-builder.mjs), this week's games for matching, and the saved trends on this
// device. No request to gtl-api: the history ships with the frontend, and this week's games come from the reads the
// Trends screen already makes (/personal and the trends week).
import { useCallback, useEffect, useState } from 'react';
import { decodeHistory, readSaved, removeTrend, saveTrend, weekMatches } from '../../../../shared/trend-builder.mjs';
import { gameSheet, gamesOf } from '../../../../shared/lines-view.mjs';
import { savedLines } from '../../../../shared/trends-view.mjs';

let pending = null;
/** The decoded history, loaded once per page; a failed load can be retried. */
export function loadBuilderHistory() {
  pending ??= import('../../../../shared/trends/builder-history.json')
    .then(module => decodeHistory(module.default))
    .catch(error => { pending = null; throw error; });
  return pending;
}

export function useBuilderHistory(enabled = true) {
  const [state, setState] = useState({ status: 'loading', history: null });
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    if (!enabled) return undefined;
    let live = true;
    setState(current => (current.status === 'ready' ? current : { status: 'loading', history: null }));
    loadBuilderHistory().then(history => { if (live) setState({ status: 'ready', history }); }, () => { if (live) setState({ status: 'error', history: null }); });
    return () => { live = false; };
  }, [enabled, attempt]);
  const retry = useCallback(() => setAttempt(n => n + 1), []);
  return { ...state, retry };
}

const CHANGED = 'gtl:saved-trends';
/** Saved trends on this device, kept in step across screens and tabs. Writes report `false` when storage refused. */
export function useSavedTrends() {
  const [items, setItems] = useState(() => readSaved());
  useEffect(() => {
    const sync = () => setItems(readSaved());
    window.addEventListener(CHANGED, sync);
    window.addEventListener('storage', sync);
    return () => { window.removeEventListener(CHANGED, sync); window.removeEventListener('storage', sync); };
  }, []);
  const announce = () => { try { window.dispatchEvent(new Event(CHANGED)); } catch { /* no window */ } };
  const save = useCallback(spec => { const result = saveTrend(spec); setItems(result.items); announce(); return result; }, []);
  const remove = useCallback(id => { const result = removeTrend(id); setItems(result.items); announce(); return result; }, []);
  return { items, save, remove };
}

/**
 * This week's games for matching, from the Trends screen's own reads (useLinesData): each game's week-file entry, the
 * viewer's gate and the viewer's own saved line per open market (nflverse convention). Null until the week file for the
 * shown week is in hand.
 */
export function weekGamesFor(lines) {
  const { personal, community, trendsWeek, trends, shown } = lines;
  if (!personal?.data || !trendsWeek || !shown || trendsWeek.season !== shown.season || trendsWeek.week !== shown.week) return null;
  return gamesOf(personal.data)
    .map(g => gameSheet({ personal: personal.data, community, trends: trendsWeek, trendsStatus: trends?.status, gameId: g.id }))
    .filter(v => v?.trendsGame)
    .map(v => ({ id: v.id, title: v.title, entry: v.trendsGame, season: trendsWeek.season, access: v.access, lines: savedLines(v.saved), started: v.started, rules: v.rules }));
}

/** Matches this week for every saved trend: `{ [id]: { matches, waiting, rows } }`, or null while the week loads. */
export function savedMatches(items, games, week) {
  if (!games) return null;
  return Object.fromEntries(items.map(item => [item.id, weekMatches(item.spec, { games, week })]));
}
